Note 1 to entry: "Used" in the context of this indicator means the net amount of water used (including any water consumed) in the course of the business activity (3.3), discounting the amount of water applied that is reclaimed or recycled for further use.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'water_efficiency_indicator_calc') AND w.code = 'ISO-46001-04' AND s.code = 'ISO-46001';
