SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'plant_recycling_rate_calc', 'Anlagen-/Standort-Recyclingrate aus dem Register (Formula (C.3))', 'number', '%', false, 'Annex C, Formula (C.3)', 'Plan 3: Ausgabe der Gleichung ISO-46001-08-D4 — (Σ Rp + Σ Rnp) / (Σ Rp + Σ Rnp + Σ WD) × 100 %; Zwilling der geprüften Gleichung C.3 (plant_recycling_rate, an -04 / -05 vererbt, CR-038) — Umstellung STAGED (iso46001-D-15 / R-1 / G-4).', 'imported_unverified', 'The plant/premises recycling rate (%) calculated by Formula (C.3) looks at all reused/reclaimed streams within the premises.

Rp + Rnp ×100 % Rp + Rnp +WD where

(C.3)

Rp is total reused/recycled water from the process; Rnp is total reused/recycled water not from the process; An example of the plant/premise recycling rate, based on Figure C.2, is illustrated in Formula (C.4).', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'plant_recycling_rate_calc') AND w.code = 'ISO-46001-08' AND s.code = 'ISO-46001';
