SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'process_recycling_rate_calc', 'Prozess-Recyclingrate aus dem Register (Formula (C.5))', 'number', '%', false, 'Annex C, Formula (C.5)', 'Plan 3: Ausgabe der Gleichung ISO-46001-08-D5 — Σ Rp / (Σ Wp + Σ Rpp) × 100 %; Zwilling der geprüften Gleichung C.5 (process_recycling_rate, an -04 / -05 vererbt, CR-038) — Umstellung STAGED (iso46001-D-16 / R-1 / G-4).', 'imported_unverified', 'The process recycling rate (%) shown in Formula (C.5) only looks at reused/reclaimed streams within the process.

Rp ×100 % Wp + Rpp where

(C.5)

Rp is total reused/recycled water from the process; Wp is incoming water to process; Rpp is reused/ recycled water from process back to process.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'process_recycling_rate_calc') AND w.code = 'ISO-46001-08' AND s.code = 'ISO-46001';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'water_streams_count', 'Anzahl erfasster Ströme / Zähler', 'number', NULL, false, 'Annex C', 'Plan 3: Ausgabe der Gleichung ISO-46001-08-D6 — count_rows über water_streams; Vorbedingung der STAGED Gates (iso46001-G-4).', 'imported_unverified', 'After carrying out a water use review, an organization should be able to develop its own water balance chart. A water balance chart compares the total water supplied to the site to the actual water use at the equipment and process level. It will allow an organization to identify activities and functions of significant water use and problem areas, including leaks and uncontrolled losses. In order to develop an accurate water balance chart, it is desirable to measure the amount of water use.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'water_streams_count') AND w.code = 'ISO-46001-08' AND s.code = 'ISO-46001';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'recycling_streams_count', 'Anzahl Recyclingströme (Rollen Rp / Rnp / Wp / Rpp) — „if recycling is carried out“', 'number', NULL, false, 'Annex C i), Formula (C.3) / (C.5)', 'Plan 3: Ausgabe der Gleichung ISO-46001-08-D7 — count_rows über water_streams mit Rolle rp / rnp / wp / rpp („recycling streams … and the recycling rate if recycling is carried out“); IF-Guard von CR-038 (iso46001-G-4).', 'imported_unverified', 'Besides information on these streams, the water balance chart should also indicate:

i) recycling streams from source to destination and the recycling rate if recycling is carried out;

ii) locations of water meters.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'recycling_streams_count') AND w.code = 'ISO-46001-08' AND s.code = 'ISO-46001';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'meters_unverified', 'Ströme ohne dokumentierte Zählerprüfung (A.12)', 'number', NULL, false, 'A.12', 'Plan 3: Ausgabe der Gleichung ISO-46001-08-D8 — count_rows über water_streams mit leerem meter_verified_on („verification/validation tests are carried out periodically“); CR-039 (leere Bedingung) → iso46001-G-3.', 'imported_unverified', 'For water meters, the organization should ensure that verification/validation tests are carried out periodically (e.g. once every 5 years) or per frequency recommended by the meter manufacturer or supplier, whichever is more stringent, to ensure the accuracy of water meters (e.g. within ± 3 %). Full documented information of the measurements should be maintained.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'meters_unverified') AND w.code = 'ISO-46001-08' AND s.code = 'ISO-46001';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'monitoring_items', 'Mindestumfang von Monitoring und Messung (§9.1 1), sieben Punkte)', 'json', NULL, false, '§9.1 1)', 'Plan 3: Mehrfachauswahl über die sieben gedruckten Mindestpunkte; das Textfeld monitoring_breakdown bleibt (iso46001-D-38); ein Vollständigkeits-Gate (alle sieben) neben CR-030 ist STAGED (iso46001-G-3 — der Materialisierer liest keine Checklisten, iso46001-F-2).', 'imported_unverified', '9.1Monitoring, measurement, analysis and evaluation
The organization shall determine:
a) what needs to be monitored and measured;
b) the methods for monitoring, measurement, analysis and evaluation, as applicable to ensure valid results;
c) when the monitoring and measuring shall be performed;
d) when the results of the monitoring and measurement shall be analysed and evaluated;
As a minimum, the water use shall be metered.
In addition, the following shall be undertaken:
1) monitor and measure as a minimum:
-- the breakdown of types of water supplied or used in the facility, including by source;
-- the breakdown of significant water use and other outputs of the water use review;
 — -- the relevant variables related to significant water use; -- the business activity indicators; -- the water efficiency indicators; -- the effectiveness of the action plans in achieving objectives and targets; -- evaluations of actual versus expected water use. 2) apply the appropriate methods for monitoring, measurement, analysis and evaluation, as applicable, to ensure valid results; 3) identify and investigate any significant deviations in water efficiency performance; 4) evaluate compliance with legal requirements or other requirements in regard to water use, water efficiency, wastewater discharge and pollution control. The organization should define, periodically review and update/revise its measurement needs. The organization shall retain appropriate documented information as evidence of the results. The organization shall evaluate the water efficiency performance and the effectiveness of the water efficiency management system. When evaluating its water efficiency performance, the organization shall review its water use and update its action plan in the water efficiency management plan if necessary and possible.', 'select_many', '{"title":"Monitoring und Messung — Mindestumfang nach §9.1 1)","subtitle":"„monitor and measure as a minimum“ — die sieben gedruckten Punkte (ankreuzen, was überwacht und gemessen wird)","note":"9.1Monitoring, measurement, analysis and evaluation\nThe organization shall determine:\na) what needs to be monitored and measured;\nb) the methods for monitoring, measurement, analysis and evaluation, as applicable to ensure valid results;\nc) when the monitoring and measuring shall be performed;\nd) when the results of the monitoring and measurement shall be analysed and evaluated;\nAs a minimum, the water use shall be metered.\nIn addition, the following shall be undertaken:\n1) monitor and measure as a minimum:\n-- the breakdown of types of water supplied or used in the facility, including by source;\n-- the breakdown of significant water use and other outputs of the water use review;\n -- the relevant variables related to significant water use; -- the business activity indicators; -- the water efficiency indicators; -- the effectiveness of the action plans in achieving objectives and targets; -- evaluations of actual versus expected water use. 2) apply the appropriate methods for monitoring, measurement, analysis and evaluation, as applicable, to ensure valid results; 3) identify and investigate any significant deviations in water efficiency performance; 4) evaluate compliance with legal requirements or other requirements in regard to water use, water efficiency, wastewater discharge and pollution control. The organization should define, periodically review and update/revise its measurement needs. The organization shall retain appropriate documented information as evidence of the results. The organization shall evaluate the water efficiency performance and the effectiveness of the water efficiency management system. When evaluating its water efficiency performance, the organization shall review its water use and update its action plan in the water efficiency management plan if necessary and possible.","groups":[{"label":"§9.1 1) monitor and measure as a minimum","options":["water_types_by_source","significant_use_breakdown","relevant_variables","business_activity_indicators","water_efficiency_indicators","action_plan_effectiveness","actual_vs_expected"]}]}'::jsonb, NULL, NULL, '[{"value":"water_types_by_source","label_de":"the breakdown of types of water supplied or used in the facility, including by source","order_index":0},{"value":"significant_use_breakdown","label_de":"the breakdown of significant water use and other outputs of the water use review","order_index":1},{"value":"relevant_variables","label_de":"the relevant variables related to significant water use","order_index":2},{"value":"business_activity_indicators","label_de":"the business activity indicators","order_index":3},{"value":"water_efficiency_indicators","label_de":"the water efficiency indicators","order_index":4},{"value":"action_plan_effectiveness","label_de":"the effectiveness of the action plans in achieving objectives and targets","order_index":5},{"value":"actual_vs_expected","label_de":"evaluations of actual versus expected water use","order_index":6}]'::jsonb, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'monitoring_items') AND w.code = 'ISO-46001-09' AND s.code = 'ISO-46001';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'nonconformities', 'Nichtkonformitäten (§10.1; je NC: NC, Korrektur, Ursache, Maßnahme, Wirksamkeit, Nachweis, geschlossen)', 'json', NULL, false, '§10.1', 'Plan 3: Zeilen je Nichtkonformität („the nature of the nonconformities and any subsequent actions taken; the results of any corrective action“); Anzahl / offene → nc_count / nc_open (ISO-46001-10-D1 / D2). Die Textfelder bleiben (iso46001-D-39 / D-40).', 'imported_unverified', '10.1 Nonconformity and corrective action When a nonconformity occurs, the organization shall: a) react to the nonconformity and, as applicable:
-- take action to control and correct it; -- deal with the consequences; b) evaluate the need for action to eliminate the cause(s) of nonconformities, in order that it does not recur or occur elsewhere, by: -- reviewing the nonconformity; -- determining the cause of the nonconformity; -- determining if similar nonconformities exist, or could potentially occur;

© ISO 2019 ­ All rights reserved — c) implement any action needed; d) review the effectiveness of any corrective action taken; e) make changes to the water efficiency management system, if necessary. Corrective actions shall be appropriate to the effects of the nonconformities encountered. The organization shall retain documented information as evidence of: 1) the nature of the nonconformities and any subsequent actions taken; 2) the results of any corrective action. NOTE See A.15 for more information.', 'register', '{"title":"Nichtkonformitäten und Korrekturmaßnahmen (§10.1)","subtitle":"Je Nichtkonformität eine Zeile: a) Reaktion / Korrektur, b) Ursache, c) Maßnahme, d) Wirksamkeit überprüft, 1) – 2) Nachweise; „geschlossen“ nicht angekreuzt = offen","add_label":"+ Nichtkonformität","placement":"section","columns":[{"key":"nc","label":"Nichtkonformität","type":"text","required":true,"aria_label":"Art der Nichtkonformität (§10.1 1)"},{"key":"correction","label":"a) Reaktion / Korrektur","type":"text","aria_label":"Sofortmaßnahme zur Kontrolle und Korrektur (§10.1 a)"},{"key":"cause","label":"b) Ursache","type":"text","aria_label":"Ermittelte Ursache (§10.1 b)"},{"key":"action","label":"c) Korrekturmaßnahme","type":"text","aria_label":"Umgesetzte Korrekturmaßnahme (§10.1 c)"},{"key":"effectiveness_reviewed","label":"d) Wirksamkeit überprüft","type":"boolean","aria_label":"Wirksamkeit der Korrekturmaßnahme überprüft (§10.1 d)"},{"key":"evidence","label":"Nachweis / Ergebnis","type":"text","aria_label":"Dokumentierte Information: Ergebnisse der Korrekturmaßnahme (§10.1 2)"},{"key":"closed","label":"geschlossen","type":"boolean","aria_label":"Nichtkonformität geschlossen (nicht angekreuzt = offen)"}],"footer":["nc_count","nc_open"],"note":"10.1 Nonconformity and corrective action When a nonconformity occurs, the organization shall: a) react to the nonconformity and, as applicable:\n-- take action to control and correct it; -- deal with the consequences; b) evaluate the need for action to eliminate the cause(s) of nonconformities, in order that it does not recur or occur elsewhere, by: -- reviewing the nonconformity; -- determining the cause of the nonconformity; -- determining if similar nonconformities exist, or could potentially occur;\n\n© ISO 2019 ­ All rights reserved c) implement any action needed; d) review the effectiveness of any corrective action taken; e) make changes to the water efficiency management system, if necessary. Corrective actions shall be appropriate to the effects of the nonconformities encountered. The organization shall retain documented information as evidence of: 1) the nature of the nonconformities and any subsequent actions taken; 2) the results of any corrective action. NOTE See A.15 for more information. Die Textfelder nonconformity / corrective_action bleiben (iso46001-D-39 / D-40); CR-034 (Attestierung) → iso46001-G-5."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'nonconformities') AND w.code = 'ISO-46001-10' AND s.code = 'ISO-46001';
